def palindrome(word)->bool:
    are_palindrome = True
    for i in range(len(word)//2):
        if word[i] != word[-i-1]:
            are_palindrome = False
    return are_palindrome

n = int(input())
list_palindrome = []
for i in range(n):
    word = input()
    if palindrome(word):
        list_palindrome.append(word)

if list_palindrome:
    print(' '.join(list_palindrome))
else:
    print(None)
